function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 100, H / 2 - 150 + Math.cos(t + i) * 50, 20, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // trees
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W / 2 - 50, H / 2 + 50, 100, 50);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 20, 50, 0, Math.PI);
  ctx.fill();
  ctx.stroke();

  // birds
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 200, H / 2 - 200 + Math.cos(t) * 50, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + Math.sin(t) * 200, H / 2 - 200 + Math.cos(t) * 50);
  ctx.lineTo(W / 2 + Math.sin(t) * 200 + Math.cos(t) * 20, H / 2 - 220 + Math.cos(t) * 50);
  ctx.stroke();

  ctx.restore();
}
